"""Apply static VB/IB section views after the complete IPC v2 preparation."""
from pathlib import Path
import argparse
import hashlib
import json
import re
import shutil
import subprocess

ROOT = Path(__file__).resolve().parents[1]


def prepare(source):
    receipt_path = ROOT / 'work/ipc-full-build.json'
    receipt = json.loads(receipt_path.read_text())
    if receipt['build_id'] != 'ldb-ipc-full-dev+9f30cbf7ddabdb95':
        raise RuntimeError('Expected verified full IPC v2 baseline before mapped overlay')
    baseline = ROOT / 'work/vbib-mapped-baseline'
    baseline.mkdir(parents=True, exist_ok=True)
    shutil.copy2(source / 'bridge/src/client/lockable_buffer.h', baseline / 'lockable_buffer.h')
    patch = ROOT / 'patches/vbib-mapped.patch'
    subprocess.run(['git', 'apply', '--check', str(patch)], cwd=source, check=True)
    subprocess.run(['git', 'apply', str(patch)], cwd=source, check=True)
    helper = ROOT / 'experiments/vbib-mapped/buffer_mapped_shadow.h'
    shutil.copy2(helper, source / 'bridge/src/client/buffer_mapped_shadow.h')
    menu_patch = ROOT / 'patches/l4n-config-menu.patch'
    subprocess.run(['git', 'apply', '--check', str(menu_patch)], cwd=source, check=True)
    subprocess.run(['git', 'apply', str(menu_patch)], cwd=source, check=True)
    receipt['ipc_foundation_build'] = receipt['build_id']
    version = (ROOT / 'VERSION').read_text().strip()
    if not re.fullmatch(r'\d+\.\d+\.\d+-pre\.\d+', version):
        raise RuntimeError('Mapped integration packaging requires an explicit prerelease version')
    options = (source / 'bridge/src/util/config/global_options.h').read_text()
    client_options = (source / 'bridge/src/client/client_options.h').read_text()
    if 'getOption<uint32_t>("client.ipcBatchSize", 8)' not in options:
        raise RuntimeError('Expected C8 source default')
    if 'getOption<bool>("client.vbibMappedShadow", false)' not in client_options:
        raise RuntimeError('Expected opt-in mapped shadow source default')
    digest = hashlib.sha256(receipt['protocol_source_sha256'].encode())
    digest.update(b'prerelease-version\0' + version.encode() + b'\0')
    for path in (patch, helper, menu_patch):
        digest.update(path.relative_to(ROOT).as_posix().encode() + b'\0'
                      + path.read_bytes().replace(b'\r\n', b'\n') + b'\0')
    sha = digest.hexdigest()
    stamp = source / 'bridge/src/util/ipc_v2/ipc_v2_build.h'
    stamp.write_text(''.join(f'#define LDB_IPC_V2_BUILD{i} 0x{sha[i*8:i*8+8]}u\n' for i in range(4)))
    receipt.update(build_id='l4d2-' + version + '+' + sha[:16], protocol_source_sha256=sha,
                   release_version=version, default_batch=8,
                   variant='vbib-map', install_document='docs/RELEASE-V1.3.0-pre.1.md',
                   mapped_static_vbib=True, mapped_minimum_bytes=262144,
                   mapped_idle_cache_bytes=33554432, mapped_default_enabled=False)
    receipt['package_suffix'] = '-l4n-menu-' + sha[:16]
    receipt_path.write_text(json.dumps(receipt, indent=2) + '\n')
    print(receipt['build_id'])


if __name__ == '__main__':
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--source', type=Path, default=ROOT / '.deps/dxvk-remix')
    prepare(parser.parse_args().source.resolve())
